<template>
  <section class="flex flex-col gap-4">
    <PageTitle :title="pageTitle">
      <template v-if="data">
        <Badge :variant="data.is_active ? 'success' : 'warning'">{{ data.is_active ? 'Active' : 'Paused' }}</Badge>
        <Badge :variant="getCampaignUrgency(data.urgency_level).variant">
          {{ getCampaignUrgency(data.urgency_level).label }}
        </Badge>
      </template>
    </PageTitle>
    <div class="flex flex-row flex-wrap items-center justify-between gap-2">
      <GoBackButton :subject="backSubject" :fallback-to="backTo" />
      <div v-if="!isEditRoute && data" class="flex items-center gap-2">
        <template v-if="isAdmin">
          <NuxtLink :to="{ name: 'recruitment-campaigns-id-edit', params: { id: campaignId } }">
            <Button variant="outline" :prepend-icon="Edit2Icon">Edit Campaign</Button>
          </NuxtLink>
          <ConfirmationDialog
            v-if="data.is_active"
            title="Pause campaign?"
            description="This will stop automated outreach for this campaign until resumed."
            confirm-btn-text="Pause"
            confirm-btn-variant="destructive"
            :is-confirm-loading="isPauseCampaignLoading"
            :confirm-handler="onPause"
          >
            <Button variant="outline" :prepend-icon="PauseIcon">Pause Campaign</Button>
          </ConfirmationDialog>
          <ConfirmationDialog
            v-else
            title="Resume campaign?"
            description="This will resume automated outreach for this campaign."
            confirm-btn-text="Resume"
            confirm-btn-variant="default"
            :is-confirm-loading="isResumeCampaignLoading"
            :confirm-handler="onResume"
          >
            <Button variant="outline" :prepend-icon="PlayIcon">Resume Campaign</Button>
          </ConfirmationDialog>
        </template>
        <NuxtLink :to="{ name: 'recruitment-messages', query: { campaign_ids: campaignId } }">
          <Button variant="outline" :prepend-icon="MailIcon">Messages</Button>
        </NuxtLink>
        <NuxtLink v-if="!isStatsRoute" :to="{ name: 'recruitment-campaigns-id-stats', params: { id: campaignId } }">
          <Button variant="default" :prepend-icon="ChartColumnIcon">Dashboard</Button>
        </NuxtLink>
      </div>
    </div>

    <AppLoader v-if="isLoading" subject="campaign" />
    <AppError
      v-else-if="error"
      :error="error"
      :title="isNotFound ? 'Campaign not found' : 'Failed to load campaign'"
      :to="isNotFound ? notFoundTo : undefined"
      :action-text="isNotFound ? notFoundActionText : undefined"
    />
    <AppEmpty v-else-if="!data" subject="campaign details" />
    <NuxtPage v-else :campaign="data" />
  </section>
</template>

<script setup lang="ts">
import { ChartColumnIcon, Edit2Icon, MailIcon, PauseIcon, PlayIcon } from 'lucide-vue-next';
import { getCampaignDetails, type GetCampaignDetailsResponse } from '~/client';
import { getCampaignUrgency } from '~/constants/recruitment/campaignUrgencyConfig';
import { usePauseCampaign } from '~/mutations/recruitment/pauseCampaign';
import { useResumeCampaign } from '~/mutations/recruitment/resumeCampaign';

definePageMeta({
  roles: ['admin', 'manager'],
});

const route = useRoute();
const { isAdmin } = useUserRole();

const campaignId = computed(() => useRoute('recruitment-campaigns-id').params.id);

const isEditRoute = computed(() => String(route.name) === 'recruitment-campaigns-id-edit');

const isStatsRoute = computed(() => String(route.name) === 'recruitment-campaigns-id-stats');

// Fallback targets for a deep link or fresh session, when the journey stack has no parent to go back to.
// Edit and the dashboard are both opened from the details page, so that is where they fall back to - except
// for a manager, who cannot open details at all and falls back to the project recruitment page instead.
const isChildOfDetails = computed(() => isEditRoute.value || (isStatsRoute.value && isAdmin.value));

const backTo = computed(() => {
  if (isChildOfDetails.value) return { name: 'recruitment-campaigns-id', params: { id: campaignId.value } };
  if (isAdmin.value) return { name: 'recruitment-campaigns' };
  const projectId = data.value?.project.id;
  return projectId ? { name: 'projects-id-recruitment', params: { id: projectId } } : { name: 'projects' };
});

// backTo cannot be reused here: on the edit route it points at this campaign's details page, which is the
// page that just 404'd. The campaigns list is admin-only, so a manager is sent to projects instead.
const notFoundTo = computed(() => (isAdmin.value ? { name: 'recruitment-campaigns' } : { name: 'projects' }));

const notFoundActionText = computed(() => (isAdmin.value ? 'Back to campaigns' : 'Back to projects'));

const backSubject = computed(() => {
  if (isChildOfDetails.value) return 'campaign';
  return isAdmin.value ? 'campaigns' : 'recruitment';
});

const pageTitle = computed(() => {
  const name = data.value?.name ?? 'Campaign';
  return isEditRoute.value ? `${name} - Edit` : name;
});

const { data, error, isLoading } = useQuery({
  // Key shared with the pause/resume/update mutation invalidations (['recruitment-campaign', id]).
  key: () => ['recruitment-campaign', campaignId.value],
  query: (): Promise<GetCampaignDetailsResponse> =>
    getCampaignDetails({ composable: '$fetch', path: { campaign_id: campaignId.value } }),
  enabled: () => !!campaignId.value && String(route.name).startsWith('recruitment-campaigns-id'),
});

const isNotFound = computed(() => error.value?.statusCode === 404);

useHead({
  title: () => data.value?.name ?? 'Campaign',
});

const { pauseCampaign, isPauseCampaignLoading } = usePauseCampaign();
const { resumeCampaign, isResumeCampaignLoading } = useResumeCampaign();

async function onPause() {
  if (!data.value) return;
  await pauseCampaign(data.value.id);
}

async function onResume() {
  if (!data.value) return;
  await resumeCampaign(data.value.id);
}
</script>
