import { resumeCampaign } from '~/client';
import type { ResumeCampaignResponse } from '~/client';

export const useResumeCampaign = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (campaignId: string): Promise<ResumeCampaignResponse> =>
      resumeCampaign({
        composable: '$fetch',
        path: { campaign_id: campaignId },
      }),
    onSuccess: (_, campaignId) => {
      queryCache.invalidateQueries({ key: ['recruitment-campaign', campaignId] });
      queryCache.invalidateQueries({ key: ['recruitment-campaigns.list'] });
      queryCache.invalidateQueries({ key: ['recruitment-campaigns.selector'] });
      showToastSuccess('Campaign resumed successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    resumeCampaign: mutateAsync,
    isResumeCampaignLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
