import { pauseCampaign } from '~/client';
import type { PauseCampaignResponse } from '~/client';

export const usePauseCampaign = defineMutation(() => {
  const queryCache = useQueryCache();
  const { mutateAsync, asyncStatus } = useMutation({
    mutation: (campaignId: string): Promise<PauseCampaignResponse> =>
      pauseCampaign({
        composable: '$fetch',
        path: { campaign_id: campaignId },
      }),
    onSuccess: (_, campaignId) => {
      queryCache.invalidateQueries({ key: ['recruitment-campaign', campaignId] });
      queryCache.invalidateQueries({ key: ['recruitment-campaigns.list'] });
      queryCache.invalidateQueries({ key: ['recruitment-campaigns.selector'] });
      showToastSuccess('Campaign paused successfully');
    },
    onError: (error) => {
      showToastError(error);
    },
  });

  return {
    pauseCampaign: mutateAsync,
    isPauseCampaignLoading: computed(() => asyncStatus.value === 'loading'),
  };
});
